WITH base AS (SELECT *, LOWER(method) AS method_lower FROM payments WHERE paid_at > DATE '2023-06-10'), base_payments AS (SELECT *, SUBSTRING(status, 1, 3) AS status_prefix FROM base WHERE method NOT IN ('cash', 'paypal', 'bank_transfer') AND paid_at >= TIMESTAMP '2023-05-04 14:00:00'), with_windows AS (SELECT *, MAX(amount) OVER w_running AS last4_max_amount, AVG(amount) OVER w_running AS last4_avg_amount, SUM(amount) OVER w_running AS last4_sum_amount, LAST_VALUE(amount, TRUE) OVER w_hist AS last_known_amount FROM base_payments WINDOW w_running AS (PARTITION BY method, status ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_hist AS (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT *, AVG(last4_sum_amount) OVER (PARTITION BY method ORDER BY last4_max_amount, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS last4_sum_amount_avg_6_prior, ROW_NUMBER() OVER (PARTITION BY status ORDER BY paid_at DESC, id) AS seq_no FROM with_windows WHERE amount > 800) SELECT id, order_id, status, method_lower, status_prefix, last4_avg_amount, last4_sum_amount, last_known_amount, seq_no, COUNT(seq_no) OVER (PARTITION BY order_id, method ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS seq_no_count_90d, ROW_NUMBER() OVER (PARTITION BY status, order_id ORDER BY last_known_amount, id) AS seq_no_2, NTILE(3) OVER (PARTITION BY status ORDER BY last_known_amount, id) AS last_known_amount_bucket FROM enriched;
